#           /path/to/ctor_dtor.csv
#           -o /dir/to/output

import argparse
import csv
from collections import defaultdict
from pathlib import Path

import matplotlib.pyplot as plt
from matplotlib.backends.backend_pdf import PdfPages


CONFIG = ["num_threads", "num_tasks", "vec_size"]
TIME = ["time_wall_clock_median", "time_wall_clock_min",
        "time_wall_clock_max"]


def load_csv(path):
    with path.open(newline="", encoding="utf-8-sig") as f:
        rows = list(csv.DictReader(f))

    for row in rows:
        for column in CONFIG + TIME:
            row[column] = float(row[column])
    return rows


def fmt(value):
    return str(int(value)) if value.is_integer() else f"{value:g}"


def annotate_point(ax, x, row):
    """Label a point with median and observed min–max, in milliseconds."""
    median = row["time_wall_clock_median"] * 1000
    minimum = row["time_wall_clock_min"] * 1000
    maximum = row["time_wall_clock_max"] * 1000

    label = f"{median:.2f} [{minimum:.2f}–{maximum:.2f}]"

    ax.annotate(
        label,
        (x, median),
        xytext=(5, 5),
        textcoords="offset points",
        fontsize=7,
        rotation=0,
        ha="left",
        va="bottom",
    )


def plot_factor(rows, factor, fixed, output, title):
    groups = defaultdict(list)

    for row in rows:
        key = tuple(row[c] for c in fixed)
        groups[key].append(row)

    with PdfPages(output) as pdf:
        for key, group in sorted(groups.items()):
            fig, ax = plt.subplots(figsize=(9, 5.5))

            if factor == "executable":
                names = sorted({r["executable"] for r in group})
                positions = {name: i for i, name in enumerate(names)}

                for name in names:
                    matching = [r for r in group
                                if r["executable"] == name]

                    for j, row in enumerate(matching):
                        x = positions[name] + (
                            j - (len(matching) - 1) / 2
                        ) * 0.08

                        median = row[TIME[0]] * 1000
                        low = (row[TIME[0]] - row[TIME[1]]) * 1000
                        high = (row[TIME[2]] - row[TIME[0]]) * 1000

                        ax.errorbar(
                            x, median,
                            yerr=[[max(0, low)], [max(0, high)]],
                            fmt="o", linestyle="none", capsize=4,
                        )

                        annotate_point(ax, x, row)

                ax.set_xticks(range(len(names)), names, rotation=30,
                              ha="right")
                ax.set_xlabel("Executable")

            else:
                values = sorted({r[factor] for r in group})
                positions = {v: i for i, v in enumerate(values)}
                names = sorted({r["executable"] for r in group})

                step = min(0.12, 0.48 / max(1, len(names)))
                offsets = {
                    name: (i - (len(names) - 1) / 2) * step
                    for i, name in enumerate(names)
                }

                for name in names:
                    matching = [r for r in group
                                if r["executable"] == name]

                    xs, ys, lows, highs = [], [], [], []

                    for row in matching:
                        median = row[TIME[0]] * 1000
                        xs.append(positions[row[factor]] + offsets[name])
                        ys.append(median)
                        lows.append(max(
                            0, (row[TIME[0]] - row[TIME[1]]) * 1000
                        ))
                        highs.append(max(
                            0, (row[TIME[2]] - row[TIME[0]]) * 1000
                        ))

                    ax.errorbar(
                        xs, ys, yerr=[lows, highs],
                        fmt="o", linestyle="none", capsize=3,
                        markersize=5, label=name,
                    )

                    for x, row in zip(xs, matching):
                        annotate_point(ax, x, row)

                        ax.set_xticks(
                            range(len(values)), [fmt(v) for v in values]
                        )
                ax.legend(title="Executable", fontsize="small")

                labels = {
                    "num_threads": "Number of threads",
                    "num_tasks": "Number of tasks",
                }
                ax.set_xlabel(labels[factor])

            config = ", ".join(
                f"{col}={fmt(val)}" for col, val in zip(fixed, key)
            )
            ax.set_title(f"{title}\nFixed configuration: {config}")
            ax.set_ylabel("Median wall-clock time (ms)")
            ax.grid(axis="y", alpha=0.3)
            fig.tight_layout()
            pdf.savefig(fig)
            plt.close(fig)

    print(f"Saved {output} ({len(groups)} pages)")


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("input", nargs="?", default="ctor_dtor.csv")
    parser.add_argument("-o", "--out-dir", default="plots")
    args = parser.parse_args()

    rows = load_csv(Path(args.input))
    if not rows:
        parser.error("No benchmark rows found.")

    out = Path(args.out_dir)
    out.mkdir(parents=True, exist_ok=True)

    plots = [
        ("num_threads", ["num_tasks", "vec_size"],
         "B - Impact of thread count", "B_threads.pdf"),

        ("executable", ["num_threads", "num_tasks", "vec_size"],
         "C - Impact of executable type", "C_executable.pdf"),

        ("num_tasks", ["num_threads", "vec_size"],
         "D - Impact of task count", "D_tasks.pdf"),
    ]

    for factor, fixed, title, filename in plots:
        plot_factor(
            rows, factor, fixed, out / filename, title
        )


if __name__ == "__main__":
    main()
